-- U1 platform: audit log, lifecycle holds and the shared change-function building blocks.
-- Schema-neutral: the migration runner sets the session search path to the target schema,
-- and every function pins its own schema with `set search_path from current` (BR1.5).
-- Conventions (BR3.1): uuid primary keys generated by the database, scope as columns,
-- integer version on mutable records, timestamps in UTC (timestamptz).

-- Actor of a change. The account is derived from the signed-in session; a verified system actor
-- (the operator command and the seed, running as a trusted database role) is the nil account.
-- Nothing here ever takes the actor as a parameter (BR3.9).
create or replace function platform_system_account() returns uuid
language sql immutable set search_path from current
as $$ select '00000000-0000-0000-0000-000000000000'::uuid $$;

create or replace function platform_caller_is_system() returns boolean
language sql stable security definer set search_path from current
as $$ select coalesce(nullif(current_setting('role', true), 'none'), session_user) in ('postgres', 'service_role', 'supabase_admin') $$;

create or replace function platform_actor_account() returns uuid
language plpgsql stable security definer set search_path from current
as $$
declare v_uid uuid;
begin
  if platform_caller_is_system() then
    return platform_system_account();
  end if;
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'platform: no signed-in session' using errcode = '28000';
  end if;
  return v_uid;
end $$;

-- Role of the actor in an organization, taken from the account's active grants (strongest wins).
-- An account without a grant is recorded as 'none' so a denied attempt is still attributable.
create or replace function platform_actor_role(p_organization_id uuid) returns text
language plpgsql stable security definer set search_path from current
as $$
declare v_account uuid; v_role text;
begin
  v_account := platform_actor_account();
  if platform_caller_is_system() then
    return 'system';
  end if;
  select case g.role
      when 'super_admin' then 'super_admin'
      when 'group_admin' then 'group_admin'
      when 'kindergarten_teacher' then 'teacher'
      else 'parent' end
    into v_role
    from app_role_grants g
   where g.subject_id = v_account and g.revoked_at is null
     and g.organization_id = p_organization_id
     and g.role in ('super_admin', 'group_admin', 'kindergarten_teacher', 'parent')
   order by case g.role when 'super_admin' then 1 when 'group_admin' then 2 when 'kindergarten_teacher' then 3 else 4 end
   limit 1;
  return coalesce(v_role, 'none');
end $$;

-- One append-only record of a role change, approval, import or lifecycle action (BR3.2, BR3.4).
create table audit_events (
  id uuid primary key default gen_random_uuid(),
  actor_account_id uuid not null,
  actor_role text not null check (actor_role in ('parent', 'teacher', 'group_admin', 'super_admin', 'system', 'none')),
  action text not null check (action in (
    'role.grant', 'role.revoke', 'role.first_super_admin',
    'approval.approve', 'approval.reject',
    'import.commit',
    'lifecycle.anonymize', 'lifecycle.delete', 'lifecycle.hold_place', 'lifecycle.hold_release'
  )),
  target_type text not null check (char_length(target_type) between 1 and 64),
  target_id uuid not null,
  organization_id uuid not null,
  group_id uuid,
  outcome text not null check (outcome in ('success', 'denied')),
  details text check (details is null or (char_length(details) <= 500 and details ~ '^[a-z0-9_.:-]*$')),
  occurred_at timestamptz not null default now()
);
create index audit_events_actor on audit_events (actor_account_id, occurred_at desc);
create index audit_events_target on audit_events (target_type, target_id, occurred_at desc);
create index audit_events_time on audit_events (occurred_at desc);
alter table audit_events enable row level security;
revoke all on audit_events from public, anon, authenticated, service_role;

create or replace function audit_events_refuse_change() returns trigger
language plpgsql set search_path from current
as $$ begin
  raise exception 'audit_events is append-only' using errcode = '42501';
end $$;
create trigger audit_events_append_only before update or delete on audit_events
  for each row execute function audit_events_refuse_change();

-- The only way to write an event. Not callable by any application role (BR3.9): only the named
-- change functions below (owned by the same trusted role) call it, inside their transaction.
create or replace function platform_audit_write(
  p_action text, p_target_type text, p_target_id uuid, p_organization_id uuid,
  p_group_id uuid, p_outcome text, p_details text
) returns uuid
language plpgsql security definer set search_path from current
as $$
declare v_id uuid;
begin
  insert into audit_events (actor_account_id, actor_role, action, target_type, target_id,
                            organization_id, group_id, outcome, details)
  values (platform_actor_account(), platform_actor_role(p_organization_id), p_action, p_target_type,
          p_target_id, p_organization_id, p_group_id, p_outcome, p_details)
  returning id into v_id;
  return v_id;
end $$;
revoke all on function platform_audit_write(text, text, uuid, uuid, uuid, text, text) from public, anon, authenticated, service_role;
revoke all on function platform_actor_account(), platform_actor_role(uuid), platform_caller_is_system() from public, anon, authenticated, service_role;

-- Generic optimistic-version trigger for mutable records (BR3.8): the version rises by one on
-- each accepted update. Callers add `where version = <the version they read>` to their update.
create or replace function platform_touch_version() returns trigger
language plpgsql set search_path from current
as $$ begin
  new.version := old.version + 1;
  new.updated_at := now();
  return new;
end $$;

-- A hold that stops a record from being anonymized or deleted until it is released (BR3.5).
create table lifecycle_holds (
  id uuid primary key default gen_random_uuid(),
  target_type text not null check (char_length(target_type) between 1 and 64),
  target_id uuid not null,
  organization_id uuid not null,
  reason text not null check (char_length(reason) between 1 and 300 and reason ~ '^[a-z0-9_.:-]+$'),
  placed_by_account_id uuid not null,
  placed_at timestamptz not null default now(),
  released_at timestamptz,
  version integer not null default 1 check (version >= 1),
  updated_at timestamptz not null default now()
);
create unique index lifecycle_holds_one_open on lifecycle_holds (target_type, target_id) where released_at is null;
create index lifecycle_holds_organization on lifecycle_holds (organization_id, placed_at desc);
alter table lifecycle_holds enable row level security;
revoke all on lifecycle_holds from public, anon, authenticated, service_role;

-- A hold may be updated only by its release; a released hold and the history are kept.
create or replace function lifecycle_holds_guard() returns trigger
language plpgsql set search_path from current
as $$ begin
  if tg_op = 'DELETE' then
    raise exception 'lifecycle_holds rows are retained' using errcode = '42501';
  end if;
  if old.released_at is not null
     or new.released_at is null
     or (new.id, new.target_type, new.target_id, new.organization_id, new.reason, new.placed_by_account_id, new.placed_at)
        is distinct from
        (old.id, old.target_type, old.target_id, old.organization_id, old.reason, old.placed_by_account_id, old.placed_at) then
    raise exception 'a lifecycle hold may only be updated by releasing it' using errcode = '42501';
  end if;
  new.version := old.version + 1;
  new.updated_at := now();
  return new;
end $$;
create trigger lifecycle_holds_release_only before update or delete on lifecycle_holds
  for each row execute function lifecycle_holds_guard();
